// R102.a: the whole import through the helper (ADR 0176), against the synthetic .skp fixtures
// (tests/fixtures/skp/, generated by tests/fixtures/skp/generate.cpp - provenance in
// SKP-SOURCE.txt). For each fixture the helper is run three ways (--probe, --import,
// --dry-run) and the imported package is decoded with the checked decoder:
//   S1: the decoded counts equal the helper's --probe counts;
//   S2: the bounding box in metres equals the parser's inches x 0.0254 within 1e-6 m;
//   S6: every refusal - a non-skp file, an oversize file (test-only size bound), a truncated
//       file and a pre-2013 header.
// Needs sketchyup-skp-worker (SKP_WORKER_PATH); the --real target (skp_import_real) also
// takes the owner's own file, local-only (never committed); it exits 77 (skipped) when that
// file is not on this machine.
#include "io/skp_package.hpp"
#include <QCoreApplication>
#include <QFile>
#include <QJsonArray>
#include <QJsonObject>
#include <QJsonDocument>
#include <QProcess>
#include <QTemporaryDir>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <string>
#include <tuple>
#include <vector>
using namespace sketchy;
namespace {
int failures = 0;
void check(bool ok, const std::string& message) {
    if (!ok) {
        std::cerr << "FAIL: " << message << "\n";
        ++failures;
    }
}
bool within(double a, double b, double tolerance = 1e-6) {
    return std::abs(a - b) <= tolerance;
}
QString fixture(const QString& name) { return QStringLiteral(SOURCE_DIR "/tests/fixtures/skp/") + name; }
std::vector<std::uint8_t> readAll(const QString& path, bool& ok) {
    std::ifstream in(path.toStdString(), std::ios::binary);
    std::vector<std::uint8_t> out;
    if (in) out.assign(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
    ok = !out.empty();
    return out;
}
struct RunResult {
    int exitCode;
    std::string out;
    QJsonObject report;  // the single final R line, {} when there is none
};
RunResult run(const std::vector<QString>& args, int timeoutMs = 120000) {
    QProcess process;
    QStringList list;
    for (const auto& a : args) list << a;
    process.start(QStringLiteral(SKP_WORKER_PATH), list);
    check(process.waitForFinished(timeoutMs), "the .skp worker did not finish: " +
                                               process.readAllStandardError().toStdString());
    RunResult result;
    result.exitCode = process.exitCode();
    const auto output = process.readAllStandardOutput();
    result.out = output.toStdString();
    for (const auto line : output.split('\n')) {
        const auto text = line.toStdString();
        if (text.rfind("R ", 0) == 0) result.report = QJsonDocument::fromJson(line.mid(2)).object();
    }
    return result;
}
long long count(const QJsonObject& object, const char* key) {
    return static_cast<long long>(object.value(key).toDouble(-1));
}
std::string jstr(const QJsonValue& value) { return value.toString().toStdString(); }


// The fixture's package, imported through the worker and decoded with the checked decoder.
sketchy::SkpPackage decodedFixture(const char* name, const QTemporaryDir& temp) {
    const auto out = temp.path() + QString("/shape_%1.skp-package").arg(name);
    const auto r = run({"--import", fixture(name), "--output", out});
    check(r.exitCode == 0, std::string("the import of ") + name + ": " + jstr(r.report["message"]));
    bool read;
    const auto bytes = readAll(out, read);
    check(read, "read the package for " + std::string(name));
    return decodeSkpPackage(bytes);
}
}  // namespace
int main(int argc, char** argv) {
    QCoreApplication app(argc, argv);
    const bool real = argc > 1 && std::string(argv[1]) == "--real";
    QTemporaryDir temp;  // one directory for the whole test; the names below are unique per case
    check(temp.isValid(), "the temporary directory");
    const char* fixtures[] = {
        "box.skp", "face_with_hole.skp", "soft_smooth_edges.skp", "two_materials.skp",
        "component_instances.skp", "hidden_tag.skp", "nested_component.skp"};
    for (const char* name : fixtures) {
        const auto path = fixture(name);
        // S6 first: the helper must refuse a file that is not a .skp.
        {
            const auto notSkp = temp.path() + QString("/%1.not-skp").arg(name);
            {
                std::ofstream out(notSkp.toStdString(), std::ios::binary);
                out << "this is not a SketchUp file";
            }
            const auto r = run({"--probe", notSkp});
            check(r.exitCode == 3, QString("the non-skp refusal for %1 (exit %2)").arg(name).arg(r.exitCode).toStdString());
            check(r.report["code"] == "notSkp", "the non-skp refusal for " + std::string(name) + " says " +
                                                  jstr(r.report["message"]));
        }
        // S6: an oversize file (a test-only size bound, well under the file's own size).
        {
            const auto r = run({"--import", path, "--dry-run", "--size-limit-bytes", "1024"});
            check(r.exitCode == 3, QString("the oversize refusal for %1 (exit %2)").arg(name).arg(r.exitCode).toStdString());
            check(r.report["code"] == "tooLarge", "the oversize refusal for " + std::string(name) + " says " +
                                                      jstr(r.report["message"]));
        }
        // A file the helper cannot open is unreadable, never reported as oversize.
        {
            const auto missing = temp.path() + QString("/%1.missing").arg(name);
            for (const std::vector<QString> &arguments :
                 {std::vector<QString>{"--import", missing, "--dry-run"},
                  std::vector<QString>{"--probe", missing}}) {
                const auto r = run(arguments);
                check(r.exitCode == 3 && r.report["code"] == "unreadable",
                      "a missing input is refused as unreadable (" + arguments.front().toStdString() +
                          "), not " + jstr(r.report["code"]));
            }
        }
        // S6: a truncated file.
        {
            bool read;
            const auto whole = readAll(path, read);
            check(read, "read " + path.toStdString());
            const auto truncated = temp.path() + QString("/%1.truncated").arg(name);
            {
                std::ofstream out(truncated.toStdString(), std::ios::binary);
                out.write(reinterpret_cast<const char*>(whole.data()), static_cast<std::streamsize>(whole.size() / 2));
            }
            const auto r = run({"--probe", truncated});
            check(r.exitCode == 3, QString("the truncated refusal for %1 (exit %2)").arg(name).arg(r.exitCode).toStdString());
            check(r.report["code"] == "parse", "the truncated refusal for " + std::string(name) + " says " +
                                                     jstr(r.report["code"]));
        }
        const auto probe = run({"--probe", path});
        check(probe.exitCode == 0, QString("%1: the probe (exit %2) %3").arg(name).arg(probe.exitCode).arg(QString::fromStdString(jstr(probe.report["message"]))).toStdString());
        const auto import = run({"--import", path, "--output", temp.path() + QString("/%1.skp-package").arg(name)});
        check(import.exitCode == 0, QString("%1: the import (exit %2) %3").arg(name).arg(import.exitCode).arg(QString::fromStdString(jstr(import.report["message"]))).toStdString());
        check(import.report["status"] == "ok", "the import of " + std::string(name) + " says " +
                                                jstr(import.report["status"]));
        check(import.report["bytes"].toDouble(-1) > 0, "the import of " + std::string(name) + " has no package");
        bool read;
        const auto bytes = readAll(temp.path() + QString("/%1.skp-package").arg(name), read);
        check(read && bytes.size() == import.report["bytes"].toDouble(), "the package file for " +
                                                                                std::string(name) + " does not match the report");
        const auto decoded = decodeSkpPackage(bytes);  // the digest-checked decode
        // S1: the decoded counts equal the helper's --probe counts.
        const char* keys[] = {"definitions", "vertices", "edges", "faces", "holes", "instances",
                              "materials", "tags"};
        const auto probeCounts = probe.report["counts"].toObject();
        const long long decodedCounts[8] = {decoded.counts.definitions, decoded.counts.vertices,
                                          decoded.counts.edges, decoded.counts.faces,
                                          decoded.counts.holes, decoded.counts.instances,
                                          decoded.counts.materials, decoded.counts.tags};
        for (size_t i = 0; i < 8; ++i) {
            check(count(probeCounts, keys[i]) == decodedCounts[i],
                  std::string("S1: the package count for ") + keys[i] + " (" +
                      std::to_string(decodedCounts[i]) + ") does not match the probe (" +
                      std::to_string(count(probeCounts, keys[i])) + ") for " + name);
        }
        // S2: the bounding box in metres equals the parser's inches x 0.0254 within 1e-6 m.
        if (decoded.hasBounding) {
            for (int axis = 0; axis < 3; ++axis) {
                check(within(decoded.boundingMin[axis], decoded.boundingMinInches[axis] * 0.0254),
                      "S2: the min " + std::to_string(decoded.boundingMin[axis]) +
                          " is not the inches " + std::to_string(decoded.boundingMinInches[axis]) + " x 0.0254 for " + name);
                check(within(decoded.boundingMax[axis], decoded.boundingMaxInches[axis] * 0.0254),
                      "S2: the max " + std::to_string(decoded.boundingMax[axis]) +
                          " is not the inches " + std::to_string(decoded.boundingMaxInches[axis]) + " x 0.0254 for " + name);
            }
        }
        // A dry run imports nothing.
        const auto dryRun = run({"--import", path, "--dry-run"});
        check(dryRun.exitCode == 0, std::string("the dry run of ") + name);
        check(dryRun.report["status"] == "ok", std::string("the dry run of ") + name + " says " +
                                                 jstr(dryRun.report["status"]));
    }
    // The fixtures' own shapes, decoded through the checked decoder.
    {
        bool read;
        const auto box = decodedFixture("box.skp", temp);
        check(box.hasBounding, "the box has a bounding box");
        check(within(box.boundingMin[0], 0.0) && within(box.boundingMin[1], 0.0) && within(box.boundingMin[2], 0.0), "the box starts at the origin");
        check(within(box.boundingMax[0], 0.0254) && within(box.boundingMax[1], 0.0254) && within(box.boundingMax[2], 0.0254), "the box is 1 inch on every axis");
        check(box.counts.holes == 0 && box.counts.faces == 6, "the box has 6 faces and no holes");
    }
    {
        bool read;
        const auto face = decodedFixture("face_with_hole.skp", temp);
        check(face.counts.holes == 1, "the hole face has 1 hole");
        const auto& face0 = face.definitions[0].faces.front();
        check(face0.loops.size() == 2, "the hole face keeps both loops");
    }
    {
        bool read;
        const auto component = decodedFixture("component_instances.skp", temp);
        check(component.counts.instances == 3, "the component is placed 3 times");
        check(component.definitions[0].instances.size() == 3, "the root holds the 3 instances");
        check(component.definitions[0].instances[2].hidden, "the third instance is hidden");
    }
    {
        bool read;
        const auto tagged = decodedFixture("hidden_tag.skp", temp);
        bool hidden = false;
        for (const auto& tag : tagged.tags)
            hidden |= tag.hidden;
        check(tagged.tags.size() == 2 && hidden, "the hidden layer is recorded as hidden");
    }
    {
        bool read;
        const auto painted = decodedFixture("two_materials.skp", temp);
        check(painted.counts.materials == 2, "two materials are kept");
        std::string names;
        for (const auto& material : painted.materials) names += material.name + ";";
        check(names.find("Red") != std::string::npos && names.find("Blue") != std::string::npos,
              "the materials keep their names (" + names + ")");
    }
    {
        bool read;
        const auto soft = decodedFixture("soft_smooth_edges.skp", temp);
        int softEdges = 0;
        int smoothEdges = 0;
        for (const auto& edge : soft.definitions[0].edges) {
            softEdges += edge.soft ? 1 : 0;
            smoothEdges += edge.smooth ? 1 : 0;
        }
        check(softEdges > 0 && smoothEdges > 0, "the soft and the smooth edges keep their flags");
    }
    {
        bool read;
        const auto nested = decodedFixture("nested_component.skp", temp);
        check(nested.counts.definitions == 3, "the nested component keeps both definitions and the root");
        check(nested.counts.instances == 2, "the nested and the outer instance are both kept");
    }
    // S6: the pre-2013 gate (ADR 0176 section 2). The version sits in the file's own header JSON
    // (UTF-16LE): the major of the box's "17.0.1" has its units digit at the fixed offset below.
    // 2013 to 2020 is read best-effort, so only a major below 13 is refused: "12.0.1" is refused
    // with the advice, and "13.0.1" is not refused as pre-2013 (it parses or fails as any file).
    {
        bool read;
        const auto whole = readAll(fixture("box.skp"), read);
        check(read, "read box.skp for the pre-2013 gate");
        // "SketchUp Model" (14 UTF-16 chars) after the 4-byte marker, then ff fe ff 08, then
        // the JSON { " 1 7 . 0 . 1 - the major's 7 is at byte 4 + 28 + 4 + 4.
        const size_t at = 4 + 28 + 4 + 4;
        check(at + 1 < whole.size() && whole[at] == 0x37 && whole[at + 1] == 0x00,
              "the version major is where the test expects it");
        const auto withUnits = [&](std::uint8_t digit, const char* name) {
            auto patched = whole;
            patched[at] = digit;
            const auto path = temp.path() + "/" + name;
            std::ofstream out(path.toStdString(), std::ios::binary);
            out.write(reinterpret_cast<const char*>(patched.data()), static_cast<std::streamsize>(patched.size()));
            return path;
        };
        const auto before = run({"--probe", withUnits(0x32, "pre2013.skp")});  // 12
        check(before.exitCode == 3, QString("the pre-2013 refusal (exit %1)").arg(before.exitCode).toStdString());
        check(before.report["code"] == "pre2013", "the pre-2013 refusal says " + jstr(before.report["message"]));
        const auto best = run({"--probe", withUnits(0x33, "best-effort-2013.skp")});  // 13
        check(best.report["code"].toString() != "pre2013",
              "a 2013 file is read best-effort, not refused as pre-2013: " + jstr(best.report["code"]));
    }
#ifdef CLI_PATH
    // R102.c (ADR 0176 section 9): the application's CLI, --import-skp, through the real helper, with
    // the STEP import's own contract: the compact JSON on stdout, the native file when asked, and a
    // refusal as an INPUT_ERROR on the error stream with the helper's code.
    {
        const auto cli = QString::fromUtf8(CLI_PATH);
        const auto runCli = [&cli](const QStringList& args) {
            QProcess process;
            process.start(cli, args);
            const bool finished = process.waitForStarted(10000) && process.waitForFinished(120000);
            return std::make_tuple(finished && process.exitStatus() == QProcess::NormalExit, process.exitCode(),
                                   process.readAllStandardOutput(), process.readAllStandardError());
        };
        const QString worker = QString::fromUtf8(SKP_WORKER_PATH);
        // L1a: an import of a fixture through the real helper, with a native file.
        {
            const QString out = temp.path() + "/cli-box.sketchyup";
            auto [ok, code, outText, errText] =
                runCli({"--import-skp", fixture("box.skp"), "--skp-worker", worker, "--output", out});
            check(ok && code == 0, "the CLI's SketchUp import runs: " + errText.toStdString());
            const QJsonObject result = QJsonDocument::fromJson(outText).object();
            check(result["status"].toString() == "imported", "the CLI says imported: " + outText.toStdString());
            const QJsonObject report = result["importReport"].toObject();
            check(report["format"].toString() == "SketchUp", "the CLI's report says SketchUp");
            check(report["counts"].toObject()["faces"].toInteger() > 0, "the CLI's report counts the faces");
            check(QFile::exists(out), "the CLI wrote the native file");
        }
        // L1b: a file that is not a SketchUp file is refused before the helper starts, as an INPUT_ERROR
        // with the code notSkp; nothing is written.
        {
            const QString notSkp = temp.path() + "/cli-not-skp.skp";
            {
                std::ofstream out(notSkp.toStdString(), std::ios::binary);
                out << "this is not a SketchUp file";
            }
            auto [ok, code, outText, errText] = runCli({"--import-skp", notSkp, "--skp-worker", worker});
            check(ok && code == 1, "the CLI's refusal ends 1");
            const QJsonObject result = QJsonDocument::fromJson(errText).object();
            check(result["status"].toString() == "failed" && result["code"].toString() == "INPUT_ERROR",
                  "the CLI's refusal is an INPUT_ERROR: " + errText.toStdString());
            check(result["details"].toObject()["skpCode"].toString() == "notSkp", "the CLI's refusal carries notSkp");
        }
        // L1c: a helper that is not there is the workerMissing refusal (the application's availability
        // sheet, in the window), as an INPUT_ERROR.
        {
            auto [ok, code, outText, errText] =
                runCli({"--import-skp", fixture("box.skp"), "--skp-worker", temp.path() + "/no-such-worker"});
            check(ok && code == 1, "the CLI's missing helper ends 1");
            check(QJsonDocument::fromJson(errText).object()["details"].toObject()["skpCode"].toString() ==
                      "workerMissing",
                  "the CLI's missing helper is workerMissing: " + errText.toStdString());
        }
        // L1d: the options are validated, and the operation is standalone.
        {
            auto [ok, code, outText, errText] =
                runCli({"--import-skp", fixture("box.skp"), "--skp-worker", worker, "--skp-deadline", "0"});
            check(ok && code == 1 && QJsonDocument::fromJson(errText).object()["code"].toString() == "INVALID_REQUEST",
                  "the CLI rejects a deadline below its bound: " + errText.toStdString());
            auto [ok2, code2, outText2, errText2] = runCli({"--skp-deadline", "30"});
            check(ok2 && code2 == 1 && QJsonDocument::fromJson(errText2).object()["code"].toString() == "INVALID_REQUEST",
                  "a SketchUp option without the operation is refused: " + errText2.toStdString());
            auto [ok3, code3, outText3, errText3] =
                runCli({"--import-skp", fixture("box.skp"), "--skp-worker", worker, "--step-length-unit", "mm"});
            check(ok3 && code3 == 1 && QJsonDocument::fromJson(errText3).object()["code"].toString() == "INVALID_REQUEST",
                  "the SketchUp import is standalone: " + errText3.toStdString());
        }
    }
#endif
    // The owner's own file (local only, never committed): the numbers the ADR notes record.
    // SKETCHYUP_SKP_CORPUS names the directory that holds it; unset or missing, the case skips.
    if (real) {
        const QString corpus = qEnvironmentVariable("SKETCHYUP_SKP_CORPUS");
        const QString file = corpus.isEmpty() ? QString() : corpus + QStringLiteral("/BanyanHarbor.skp");
        if (file.isEmpty() || !QFile::exists(file)) {
            std::cout << "SKETCHYUP_SKP_CORPUS does not hold the owner's file; skipped\n";
            return 77;
        }
        const auto probe = run({"--probe", file});
        check(probe.exitCode == 0, "the probe of the owner's file: " + jstr(probe.report["message"]));
        const auto c = probe.report["counts"].toObject();
        check(count(c, "definitions") == 2, "the file has 2 definitions");
        check(count(c, "vertices") == 1261, "the file has 1261 vertices (174 + 1087)");
        check(count(c, "faces") == 159, "the file has 159 faces (101 + 58)");
        check(count(c, "instances") == 1, "the file has 1 instance");
        check(count(c, "materials") == 18, "the file has 18 materials");
        check(count(c, "tags") == 1, "the file has 1 layer");
        const auto import = run({"--import", file, "--output", temp.path() + "/BanyanHarbor.skp-package"});
        check(import.exitCode == 0, "the import of the owner's file");
        bool read;
        const auto bytes = readAll(temp.path() + "/BanyanHarbor.skp-package", read);
        const auto decoded = decodeSkpPackage(bytes);
        check(decoded.counts.definitions == 2, "the package of the owner's file decodes");
        check(decoded.hasBounding, "the owner's file has a bounding box");
        for (int axis = 0; axis < 3; ++axis) {
            const double min = decoded.boundingMin[axis];
            const double max = decoded.boundingMax[axis];
            check(within(min, decoded.boundingMinInches[axis] * 0.0254), "the owner's box min, axis " + std::to_string(axis));
            check(within(max, decoded.boundingMaxInches[axis] * 0.0254), "the owner's box max, axis " + std::to_string(axis));
        }
        std::cout << "owner's file: package " << import.report["bytes"].toDouble() << " bytes, probe "
                  << QJsonDocument(probe.report["counts"].toObject()).toJson(QJsonDocument::Compact).toStdString() << "\n";
    }
    if (failures) {
        std::cerr << failures << " failures\n";
        return 1;
    }
    std::cout << "skp import tests ok\n";
    return 0;
}
